contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a1, address a2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 1);

        uint256 balA1Before = c.balances(a1); if (__ESBMC_reverted()) return;
        uint256 balA2Before = c.balances(a2); if (__ESBMC_reverted()) return;

        uint256 sumBefore = balA1Before + balA2Before;

        (bool reverted) = false;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balA1After = c.balances(a1); if (__ESBMC_reverted()) return;
        uint256 balA2After = c.balances(a2); if (__ESBMC_reverted()) return;

        uint256 sumAfter = balA1After + balA2After;

        assert(sumAfter <= sumBefore);
    }

    receive() external payable {}
}

