    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address a1, address a2) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 1);
        uint256 balA1Before;
        try c.balances(a1) returns (uint256 __r) { balA1Before = __r; } catch { return; }
        uint256 balA2Before;
        try c.balances(a2) returns (uint256 __r) { balA2Before = __r; } catch { return; }
        uint256 sumBefore = balA1Before + balA2Before;
        (bool reverted) = false;
